def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    danger_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    danger_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    high_supply = supply >= 22.0
    low_supply = supply <= 17.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    danger_prev = max(danger_bids) if danger_bids else highest_prev

    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(78.0, danger_prev + 6.0)
        if low_supply:
            bid += 10.0
        return float(min(budget, bid))

    if urgent:
        bid = max(58.0, highest_prev + 3.0)
        if low_supply:
            bid += 8.0
        elif high_supply:
            bid -= 6.0
        return float(max(0.0, min(budget, bid)))

    if high_supply:
        bid = 16.0
        if highest_prev <= 25.0:
            bid = max(bid, highest_prev + 1.0)
        elif highest_prev < 55.0:
            bid = 24.0
        else:
            bid = 14.0
    elif low_supply:
        if highest_prev < 45.0:
            bid = max(34.0, highest_prev + 2.0)
        elif highest_prev < 90.0:
            bid = 30.0
        else:
            bid = 22.0
    else:
        if highest_prev < 35.0:
            bid = max(26.0, highest_prev + 2.0)
        elif avg_prev > 90.0:
            bid = 18.0
        else:
            bid = 24.0

    if day >= 8 and budget > DAILY_SALARY * 2:
        bid += 4.0

    safe_cap = budget
    if hp >= 6 and no_water_days == 0:
        safe_cap = min(safe_cap, DAILY_SALARY * 0.65)

    return float(max(0.0, min(safe_cap, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Safety caps
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        # If alone, try to secure enough water for survival
        target = DAILY_SALARY * 0.35
        if budget <= 0:
            return 0.0
        return float(min(budget, target))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine aggressiveness from yesterday pressure
    # If someone was bidding near/above salary, expect aggressive competition today.
    aggressive_market = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply-based scaling: when supply is low, competition for water should be higher.
    # Normalize supply to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: aim to win a meaningful share without overspending.
    # When supply is scarce (low supply_norm), bid a bit more.
    scarcity_factor = 1.15 - 0.3 * supply_norm  # ~1.15 at MIN, ~0.85 at MAX

    # HP-based urgency
    if hp <= 2:
        hp_factor = 1.25
    elif hp <= 4:
        hp_factor = 1.10
    else:
        hp_factor = 0.95

    # If market is aggressive, increase bid modestly; otherwise keep it controlled.
    if aggressive_market:
        market_factor = 1.15
    else:
        market_factor = 0.95

    # Compute target bid
    target_bid = DAILY_SALARY * 0.55 * scarcity_factor * hp_factor * market_factor

    # If we know Cindy survived with very high bids yesterday, slightly bias upward
    # when her previous bid was extremely high.
    for opp_id, opp in alive_opps:
        if opp_id == 'Cindy':
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    c_bid = float(prev['bid'])
                    if c_bid >= DAILY_SALARY * 1.4:
                        target_bid *= 1.08
                except Exception:
                    pass

    # Also, if highest previous bid was not too far above our target, try to be competitive.
    # Keep within budget.
    if highest_prev_bid > 0:
        # Try to sit just above a fraction of the leader's bid, but not exceed aggressive cap.
        competitiveness = min(1.0, (highest_prev_bid / (DAILY_SALARY * 1.6)))
        target_bid = max(target_bid, highest_prev_bid * (0.65 + 0.2 * competitiveness))

    # Final constraints
    if budget <= 0:
        return 0.0

    # Never bid above budget; also avoid bidding more than a small multiple of salary
    # to prevent bankruptcy in competitive rounds.
    max_reasonable = DAILY_SALARY * 1.2
    bid = float(min(budget, max_reasonable, target_bid))

    # If we are extremely low on budget, bid what we can.
    if bid < 1e-9:
        bid = float(min(budget, DAILY_SALARY * 0.2))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                bid_amount = DAILY_SALARY * 0.3
            else:
                bid_amount = DAILY_SALARY * 0.95
        else:
            bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
    else:
        if my_status['hp'] <= 2:
            bid_amount = DAILY_SALARY * 0.9
        else:
            bid_amount = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.95)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 3:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.8)

    if day_context['supply'] < (len(alive_opponents) + 1) * WATER_REQ * 1.2:
        bid_amount *= 1.1

    final_bid = min(my_status['budget'], bid_amount)
    final_bid = max(1.0, final_bid)

    return final_bid

